import { readFileSync } from 'node:fs';

const path = process.argv[2];
const lines = readFileSync(path, 'utf8').split('\n').filter(Boolean);
const clip = (s, n) => { s = String(s ?? '').replace(/\s+/g, ' '); return s.length > n ? s.slice(0, n) + '…' : s; };
let prevT = null;
for (const line of lines) {
  let e; try { e = JSON.parse(line); } catch { continue; }
  const t = e.timestamp ? new Date(e.timestamp) : null;
  const stamp = t ? t.toISOString().slice(11, 19) : '--:--:--';
  let gap = '';
  if (t && prevT) { const d = Math.round((t - prevT) / 1000); if (d >= 30) gap = ` [+${d}s]`; }
  if (t) prevT = t;
  if (e.attachment) { console.log(`${stamp}${gap} ATTACH ${e.attachment.type || ''} ${clip(e.attachment.hookName || '', 40)}`); continue; }
  const m = e.message;
  if (!m) continue;
  const role = m.role;
  const content = Array.isArray(m.content) ? m.content : [{ type: 'text', text: m.content }];
  for (const c of content) {
    if (c.type === 'text') {
      if (!c.text || !c.text.trim()) continue;
      console.log(`${stamp}${gap} ${role.toUpperCase()}: ${clip(c.text, role === 'user' ? 3000 : 1400)}`);
    } else if (c.type === 'thinking') {
      console.log(`${stamp}${gap} think: ${clip(c.thinking, 500)}`);
    } else if (c.type === 'tool_use') {
      const i = c.input || {};
      const key = i.command ?? i.file_path ?? i.pattern ?? i.prompt ?? i.url ?? i.skill ?? JSON.stringify(i).slice(0, 200);
      console.log(`${stamp}${gap}   > ${c.name}(${clip(key, 300)})`);
    } else if (c.type === 'tool_result') {
      const txt = Array.isArray(c.content) ? c.content.map(x => x.text || '').join(' ') : c.content;
      console.log(`${stamp}${gap}   < ${c.is_error ? 'ERROR ' : ''}${clip(txt, c.is_error ? 600 : 200)}`);
    }
  }
}

